// Daily consent-expiry check (spec 005 §4.2.1).
// k8s reads use the pod ServiceAccount (Role n8n-finance-secrets: get on the two
// named Secrets). A 404 on the token Secret means "no tokens yet" and every
// account is treated as due; anything else non-200 is thrown so the error
// workflow reports it rather than printing a healthy day.
const https = require('node:https');
const fs = require('node:fs');

async function kubernetes(namespace, name) {
  const token = fs.readFileSync('/var/run/secrets/kubernetes.io/serviceaccount/token', 'utf8').trim();
  const ca = fs.readFileSync('/var/run/secrets/kubernetes.io/serviceaccount/ca.crt');
  const options = {
    hostname: 'kubernetes.default.svc',
    path: `/api/v1/namespaces/${namespace}/secrets/${name}`,
    method: 'GET',
    headers: { authorization: `Bearer ${token}` },
    ca,
    timeout: 15000,
  };
  return new Promise((resolve, reject) => {
    const request = https.request(options, (response) => {
      let raw = '';
      response.on('data', (chunk) => (raw += chunk));
      response.on('end', () => resolve({ status: response.statusCode, body: raw }));
    });
    request.on('error', reject);
    request.end();
  });
}

const stable = await kubernetes('data', 'finance-enablebanking');
if (stable.status !== 200) {
  throw new Error(
    `finance-enablebanking unreadable (HTTP ${stable.status}); check RoleBinding n8n-finance-secrets`
  );
}
const accounts = JSON.parse(
  Buffer.from(JSON.parse(stable.body).data['accounts.json'], 'base64').toString()
);

const tokens = await kubernetes('data', 'finance-enablebanking-token');
let tokensByAlias = {};
if (tokens.status === 404) {
  // renewal-owned Secret not created yet: treat every account as due
  tokensByAlias = {};
} else if (tokens.status === 200) {
  tokensByAlias = JSON.parse(
    Buffer.from(JSON.parse(tokens.body).data['tokens.json'], 'base64').toString()
  );
} else {
  throw new Error(`finance-enablebanking-token unexpected status ${tokens.status}`);
}

const due = [];
for (const [alias, cfg] of Object.entries(accounts)) {
  const entry = tokensByAlias[alias];
  const until = entry ? entry.valid_until : null;
  const days = until ? Math.floor((new Date(until) - Date.now()) / 86400000) : -1;
  if (days <= 3) {
    const when = until ? new Date(until).toISOString().slice(0, 10) : 'no token yet';
    due.push(`- *${alias}* (${cfg.institution_id || alias}): expires on ${when}`);
  }
}

const needsRenewal = due.length > 0;
return [
  {
    json: {
      needs_renewal: needsRenewal,
      accounts_due: needsRenewal ? due.join('\n') : '',
      nudge_text: needsRenewal
        ? `Enable Banking consent expiring:\n${due.join('\n')}\n\nRenew now (the bank login is the one manual step): https://automation-n8n.homelab.alvsanand.com/form/7c1f51ab-5f61-4b21-9b31-01befd1d0d02`
        : 'all consents healthy',
    },
  },
];

// Form-submission branch: mint the RS256 JWT and create the authorization
// (POST /auth). The Form Ending node then redirects the user to the consent URL.
// The JS below runs inside an n8n Code node (node built-ins available, verified
// against the live instance 2026-09-14).
const https = require('node:https');
const fs = require('node:fs');
const crypto = require('node:crypto');

async function kubernetesSecret(namespace, name) {
  const token = fs.readFileSync('/var/run/secrets/kubernetes.io/serviceaccount/token', 'utf8').trim();
  const ca = fs.readFileSync('/var/run/secrets/kubernetes.io/serviceaccount/ca.crt');
  const options = {
    hostname: 'kubernetes.default.svc',
    path: `/api/v1/namespaces/${namespace}/secrets/${name}`,
    method: 'GET',
    headers: { authorization: `Bearer ${token}` },
    ca,
    timeout: 15000,
  };
  return new Promise((resolve, reject) => {
    const request = https.request(options, (response) => {
      let raw = '';
      response.on('data', (chunk) => (raw += chunk));
      response.on('end', () => resolve({ status: response.statusCode, body: raw }));
    });
    request.on('error', reject);
    request.end();
  });
}

function requestEnableBanking(authorization, path, body) {
  const options = {
    hostname: 'api.enablebanking.com',
    path,
    method: body ? 'POST' : 'GET',
    headers: { authorization, 'content-type': 'application/json' },
    timeout: 30000,
  };
  return new Promise((resolve, reject) => {
    const request = https.request(options, (response) => {
      let raw = '';
      response.on('data', (chunk) => (raw += chunk));
      response.on('end', () => resolve({ status: response.statusCode, body: raw }));
    });
    request.on('error', reject);
    if (body) request.write(JSON.stringify(body));
    request.end();
  });
}

function base64url(object) {
  return Buffer.from(JSON.stringify(object)).toString('base64url');
}

function mintJwt(pem, appId) {
  // RSA-SHA256 over "<header>.<payload>"; iss/aud fixed by the Enable Banking
  // API reference, kid is the application id registered in the Control Panel.
  const issuedAt = Math.floor(Date.now() / 1000);
  const head = base64url({ typ: 'JWT', alg: 'RS256', kid: appId });
  const payload = base64url({
    iss: 'enablebanking.com',
    aud: 'api.enablebanking.com',
    iat: issuedAt,
    exp: issuedAt + 3600,
  });
  const signer = crypto.createSign('RSA-SHA256');
  signer.update(`${head}.${payload}`);
  signer.end();
  return `${head}.${payload}.${signer.sign(pem).toString('base64url')}`;
}

const alias = $('Form: Start Renewal').first().json['Account alias'];
const stable = await kubernetesSecret('data', 'finance-enablebanking');
if (stable.status !== 200) {
  throw new Error(`finance-enablebanking unreadable (HTTP ${stable.status}): ${stable.body}`);
}
const stableBody = JSON.parse(stable.body);
const accounts = JSON.parse(Buffer.from(stableBody.data['accounts.json'], 'base64').toString());
const config = accounts[alias];
if (!config) {
  throw new Error(`unknown alias '${alias}'; configured aliases: ${Object.keys(accounts).join(', ')}`);
}
const pem = Buffer.from(stableBody.data['private_key'], 'base64').toString();
const jwt = mintJwt(pem, config.app_id);
const authorizationBody = {
  access: { valid_until: new Date(Date.now() + 180 * 86400000).toISOString() },
  aspsp: { name: config.institution_id || alias, country: 'ES' },
  state: crypto.randomUUID(),
  redirect_url: 'https://automation-n8n.homelab.alvsanand.com/webhook/enablebanking-consent',
  psu_type: 'personal',
};
const response = await requestEnableBanking(`Bearer ${jwt}`, '/auth', authorizationBody);
if (response.status !== 200) {
  throw new Error(`POST /auth rejected (HTTP ${response.status}): ${response.body}`);
}
const consent = JSON.parse(response.body);
return [{ json: { consent_url: consent.url, alias, authorization_id: consent.authorization_id } }];

// Enable Banking consent exchange + token Secret upsert (spec 005 §4.2.1).
//
// Runs inside an n8n Code node (node built-ins available in the sandbox,
// verified against the live instance 2026-09-14). The consent code arrives on
// the bank's redirect to /webhook/enablebanking-consent?code=...; this node
// exchanges it for a session, merges the per-alias session material into
// finance-enablebanking-token (creating the Secret when it is missing - the
// renewal owns it, so ArgoCD never fights the write) and reports what it stored.
//
// Error handling: any failure here is thrown and reaches the error workflow -
// a malformed consent (no ?code=) is answered by the "Respond: Missing Code"
// branch *without* touching either API.
const https = require('node:https');
const fs = require('node:fs');
const crypto = require('node:crypto');

const SA_TOKEN_PATH = '/var/run/secrets/kubernetes.io/serviceaccount/token';
const SA_CA_PATH = '/var/run/secrets/kubernetes.io/serviceaccount/ca.crt';
const NAMESPACE = 'data';
const STABLE_SECRET = 'finance-enablebanking';
const TOKEN_SECRET = 'finance-enablebanking-token';

async function kubernetes(path, method, body) {
  const token = fs.readFileSync(SA_TOKEN_PATH, 'utf8').trim();
  const ca = fs.readFileSync(SA_CA_PATH);
  const payload = body ? JSON.stringify(body) : null;
  const options = {
    hostname: 'kubernetes.default.svc',
    path,
    method,
    headers: { authorization: `Bearer ${token}` },
    ca,
    timeout: 15000,
  };
  if (payload) {
    options.headers['content-type'] = 'application/strategic-merge-patch+json';
    options.headers['content-length'] = Buffer.byteLength(payload);
  }
  return new Promise((resolve, reject) => {
    const request = https.request(options, (response) => {
      let raw = '';
      response.on('data', (chunk) => (raw += chunk));
      response.on('end', () => resolve({ status: response.statusCode, body: raw }));
    });
    request.on('error', reject);
    if (payload) request.write(payload);
    request.end();
  });
}

function requestEnableBanking(authorization, path, body) {
  const options = {
    hostname: 'api.enablebanking.com',
    path,
    method: body ? 'POST' : 'GET',
    headers: { authorization, 'content-type': 'application/json' },
    timeout: 30000,
  };
  return new Promise((resolve, reject) => {
    const request = https.request(options, (response) => {
      let raw = '';
      response.on('data', (chunk) => (raw += chunk));
      response.on('end', () => resolve({ status: response.statusCode, body: raw }));
    });
    request.on('error', reject);
    if (body) request.write(JSON.stringify(body));
    request.end();
  });
}

function mintJwt(pem, appId) {
  // RS256 over "<header>.<payload>"; iss/aud fixed by the Enable Banking API
  // reference; kid is the application id registered in the Control Panel.
  const issuedAt = Math.floor(Date.now() / 1000);
  const head = Buffer.from(JSON.stringify({ typ: 'JWT', alg: 'RS256', kid: appId })).toString('base64url');
  const payload = Buffer.from(
    JSON.stringify({
      iss: 'enablebanking.com',
      aud: 'api.enablebanking.com',
      iat: issuedAt,
      exp: issuedAt + 3600,
    })
  ).toString('base64url');
  const signer = crypto.createSign('RSA-SHA256');
  signer.update(`${head}.${payload}`);
  signer.end();
  return `${head}.${payload}.${signer.sign(pem).toString('base64url')}`;
}

const code = $('EnableBanking Redirect').first().json.query.code;

const stable = await kubernetes(`/api/v1/namespaces/${NAMESPACE}/secrets/${STABLE_SECRET}`, 'GET');
if (stable.status !== 200) {
  throw new Error(`${STABLE_SECRET} unreadable (HTTP ${stable.status}); check RoleBinding n8n-finance-secrets`);
}
const stableBody = JSON.parse(stable.body);
const accounts = JSON.parse(Buffer.from(stableBody.data['accounts.json'], 'base64').toString());

const pem = Buffer.from(stableBody.data['private_key'], 'base64').toString();
const firstAlias = Object.keys(accounts)[0];
// Sessions are exchanged by the application that started the consent; this
// fleet uses one application (one app_id in accounts.json), so its kid signs
// the exchange. A second application needs the alias tracked through the
// consent state before this node can serve both.
const jwt = mintJwt(pem, accounts[firstAlias].app_id);

const sessionResponse = await requestEnableBanking(`Bearer ${jwt}`, '/sessions', { code });
if (sessionResponse.status !== 200) {
  throw new Error(`POST /sessions failed (HTTP ${sessionResponse.status}): ${sessionResponse.body}`);
}
const session = JSON.parse(sessionResponse.body);
const validUntil = (session.access || {}).valid_until;
if (!validUntil) {
  throw new Error(`session response carried no access.valid_until: ${sessionResponse.body}`);
}

const tokensGet = await kubernetes(`/api/v1/namespaces/${NAMESPACE}/secrets/${TOKEN_SECRET}`, 'GET');
let tokens = {};
let tokenSecretExisted = false;
if (tokensGet.status === 404) {
  // renewal-owned Secret not created yet: the upsert creates it
  tokens = {};
} else if (tokensGet.status === 200) {
  const existingData = (JSON.parse(tokensGet.body).data || {})['tokens.json'];
  tokens = existingData ? JSON.parse(Buffer.from(existingData, 'base64').toString()) : {};
  tokenSecretExisted = true;
} else {
  throw new Error(`${TOKEN_SECRET} GET failed (HTTP ${tokensGet.status}): ${tokensGet.body}`);
}

const renewals = [];
for (const resource of session.accounts || []) {
  if (!resource.uid) continue;
  const iban = (resource.account_id || {}).iban;
  const matched = Object.entries(accounts).filter(([, cfg]) => cfg.iban === iban);
  const alias = matched.length ? matched[0][0] : null;
  if (!alias) {
    throw new Error(
      `session account ****${String(iban).slice(-4)} is not in ${STABLE_SECRET} accounts.json; add its alias first`
    );
  }
  tokens[alias] = { uid: resource.uid, valid_until: validUntil };
  renewals.push(alias);
}
if (renewals.length === 0) {
  throw new Error('Enable Banking session authorized zero accounts; nothing to store');
}

const tokensJson = JSON.stringify(tokens);
const upsertBody = {
  apiVersion: 'v1',
  kind: 'Secret',
  metadata: { name: TOKEN_SECRET, namespace: NAMESPACE },
  stringData: { 'tokens.json': tokensJson },
};
if (tokenSecretExisted) {
  const replacement = await kubernetes(
    `/api/v1/namespaces/${NAMESPACE}/secrets/${TOKEN_SECRET}`,
    'PUT',
    upsertBody
  );
  if (replacement.status !== 200) {
    throw new Error(`${TOKEN_SECRET} PUT failed (HTTP ${replacement.status}): ${replacement.body}`);
  }
} else {
  const created = await kubernetes(`/api/v1/namespaces/${NAMESPACE}/secrets`, 'POST', upsertBody);
  if (created.status !== 201) {
    throw new Error(`${TOKEN_SECRET} create failed (HTTP ${created.status}): ${created.body}`);
  }
}

const untilDate = new Date(validUntil).toISOString().slice(0, 10);
return [
  {
    json: {
      result: tokenSecretExisted ? 'updated' : 'created',
      aliases_renewed: renewals,
      valid_until: untilDate,
      slack_text: `Enable Banking token renewed for ${renewals.join(', ')} (Openbank): consent valid until ${untilDate}. The daily pipeline picks it up on the next run.`,
    },
  },
];
